// Single source of truth for what each template is for. The gallery (#/kit)
// renders it, and `npm run docs` turns it into docs/components.md.
// Plain data only, no imports, so Node can read it without a bundler.
//
// Length units in `limits`: 字 = one CJK character; two Latin letters, digits
// or spaces count as one 字. 个字符 = every character counts as one (used for
// monospace and numeric fields).

export interface PropDoc {
  name: string
  type: string
  required?: boolean
  note: string
}

export interface CatalogEntry {
  /** Anchor in the gallery: #/kit/<id>. */
  id: string
  /** Export name in src/kit. */
  component: string
  name: string
  /** Where it sits in a storyline. */
  role: string
  summary: string
  useWhen: string[]
  avoidWhen: string[]
  /** Hard content limits. Exceeding them breaks the layout; `npm run qa` will flag it. */
  limits: string[]
  props: PropDoc[]
  example: string
  /** Slide id in the reference deck that demonstrates it. */
  demo: string
  /** Reference deck for the demo: src/decks/<deck>, or a Pro pack name. */
  deck: string
  interaction?: string
}

const base: PropDoc[] = [
  { name: 'kicker', type: 'string', required: true, note: '标题上方的小节名，2–8 字' },
  { name: 'title', type: 'string | string[]', required: true, note: '页面标题；传数组可手动断行，每项一行' },
  { name: 'lead', type: 'string', note: '一到两句导语，≤ 60 字' },
  { name: 'source', type: 'string', note: '事实出处；页面上有任何数据或事实时必填' },
  { name: 'hint', type: 'ReactNode', note: '页眉中间的操作提示，可用 <kbd>' },
]

